'use client';

import { useState } from 'react';

/**
 * v1 bottom nav — exact reproduction of the Figma "Nav bar" component
 * (95:117) and its two variants: Default (Puzzles active, 95:116) and
 * Variant2 (Favorites active, 95:118). Tapping a tab moves the lime highlight.
 *
 * Per the component, BOTH tabs always carry the px-16/py-12 wrapper so the pill
 * width never changes between states; only the active tab gets the lime tint
 * (rgba(151,236,3,0.09)) and lime icon/label (#9df800) — the other is grey
 * (#5c5c5c). The pill's rounded-[31px] and the tab's rounded-[15px] are
 * concentric (31 − 16 vertical padding = 15).
 *
 * Icons are the exact exported vector paths, drawn with stroke="currentColor"
 * so each tab's text colour drives its icon and animates on tap.
 *
 * Note: Figma renders the active label as Medium in the Default variant but
 * Regular in Variant2 — an inconsistency. We use Medium for whichever tab is
 * active so the weight doesn't flicker between taps.
 */
type Tab = 'puzzles' | 'favorites';

