const TABS: { id: Tab; label: string; Icon: () => React.JSX.Element }[] = [
  { id: 'puzzles', label: 'Puzzles', Icon: PuzzleIcon },
  { id: 'favorites', label: 'Favorites', Icon: StarIcon },
];

export default function NavBar({
  active,
  onChange,
}: {
  active?: Tab;
  onChange?: (tab: Tab) => void;
} = {}) {
  const [internal, setInternal] = useState<Tab>('puzzles');
  const current = active ?? internal;

  const select = (tab: Tab) => {
    setInternal(tab);
    onChange?.(tab);
  };

  return (
    <div className="absolute inset-x-0 bottom-[53px] flex justify-center">
      <div className="flex items-center gap-[24px] overflow-hidden rounded-[31px] bg-[#0d0d0d] px-[24px] py-[16px]">
        {TABS.map(({ id, label, Icon }) => {
          const on = current === id;
          return (
            <button
              key={id}
              type="button"
              onClick={() => select(id)}
              aria-pressed={on}
              className={`flex items-center gap-[6px] rounded-[15px] px-[16px] py-[12px] transition-colors duration-200 ${
                on ? 'bg-[rgba(151,236,3,0.09)] text-[#9df800]' : 'bg-transparent text-[#5c5c5c]'
              }`}
            >
              <Icon />
              <span
                className={`text-[16px] whitespace-nowrap ${on ? 'font-medium' : 'font-normal'}`}
              >
                {label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
